import requests
queries=['"tissue-specific" DLG-1 C. elegans','"protein purification" "DLG-1"','"DLG-1" interactome C. elegans','"Discs large" tissue-specific purification nematode']
for q in queries:
 r=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':10},timeout=20).json()
 print('\nQUERY',q)
 for x in r.get('resultList',{}).get('result',[]): print(x.get('pmid'),x.get('title'))

